contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "deposit must be positive");
        require(withdrawAmount == depositAmount, "withdraw must equal deposit");
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        bool depositReverted;
        bool withdrawReverted;

        c.deposit{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depositReverted = true;
        } else {
            depositReverted = false;
        }

        uint256 balanceBeforeWithdraw = address(c).balance;

        c.withdraw(withdrawAmount); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint256 balanceAfterWithdraw = address(c).balance;

        assert(depositReverted || (!withdrawReverted && balanceAfterWithdraw == balanceBeforeWithdraw - withdrawAmount));
    }

    receive() external payable {}
}

